<?php
declare(strict_types=1);
namespace CommunityHub;
final class Admin {
 const REVIEW=['reviewer',...Domain::STAFF];
 public static function handle(string $method,string $path,array $d):void{$u=Auth::requireUser(true);if(str_starts_with($path,'/admin/appearance')||str_starts_with($path,'/admin/website')||str_starts_with($path,'/community/manage')){ContentAdmin::handle($u,$method,$path,$d);return;}if(str_starts_with($path,'/admin/fivem')){IntegrationAdmin::handle($u,$method,$path,$d);return;}if(str_starts_with($path,'/lms/admin')){LearningAdmin::handle($u,$method,$path,$d);return;}if(str_starts_with($path,'/admin/application-builder')){ApplicationAdmin::handle($u,$method,$path,$d);return;}if(str_starts_with($path,'/admin/automations')){FlowAdmin::handle($u,$method,$path,$d);return;}if(str_starts_with($path,'/admin/management')||str_starts_with($path,'/personnel/')||str_starts_with($path,'/loa-management')||str_starts_with($path,'/staff-activity')||str_starts_with($path,'/command-center')){PeopleAdmin::handle($u,$method,$path,$d);return;}Domain::role($u,self::REVIEW);
  if($path==='/admin/settings/community-name'&&$method==='POST'){Domain::role($u,['owner']);App::query("INSERT INTO site_settings(setting_key,setting_value) VALUES('community_name',?) ON DUPLICATE KEY UPDATE setting_value=VALUES(setting_value)",[App::text($d['community_name']??null,'Community name',120)]);App::redirect('/admin');}
  if($path==='/admin/users'||preg_match('~^/admin/users/(\d+)/role$~',$path,$m)){Domain::role($u,['admin','owner']);if($method==='POST'){self::userRole($u,(int)$m[1],$d);App::redirect('/admin/users?q='.rawurlencode($d['q']??''));}$q=App::text($_GET['q']??'','Search',120,true);$like='%'.$q.'%';$rows=$q?App::rows('SELECT id,discord_id,discord_username,display_name,email,role FROM users WHERE discord_username LIKE ? OR display_name LIKE ? OR discord_id LIKE ? OR email LIKE ? ORDER BY display_name LIMIT 100',[$like,$like,$like,$like]):[];View::layout('Accounts & roles',function()use($q,$rows){View::heading('Accounts & roles');?><form method="get"><label>Search<input name="q" value="<?=escape($q)?>"></label><button class="btn secondary">Search</button></form><?php View::table($rows,['display_name'=>'Name','discord_username'=>'Discord','role'=>'Role'],function($r){View::form('/admin/users/'.$r['id'].'/role',['role'=>['label'=>'Community role','options'=>array_combine(['applicant','recruit','member','reviewer',...Domain::STAFF],['applicant','recruit','member','reviewer',...Domain::STAFF])]],'Update role',$r);});});return;}
  if(preg_match('~^/admin/applications/(\d+)(?:/status)?$~',$path,$m)){$id=(int)$m[1];$a=App::row('SELECT a.*,f.title form_title,f.slug form_slug,f.department_id,u.display_name FROM applications a JOIN application_forms f ON f.id=a.form_id LEFT JOIN users u ON u.id=a.user_id WHERE a.id=?',[$id]);if(!$a)throw new HttpError('Application not found.',404);if($method==='POST'){$statuses=['under_review','changes_requested','interview','accepted','denied','archived'];if(!in_array($d['status']??'',$statuses,true))throw new HttpError('Select a valid application status.');$reason=App::text($d['reason']??'','Reason',10000,true);App::transaction(function()use($u,$id,$a,$d,$reason){App::query('UPDATE applications SET status=?,reviewed_by=?,reviewed_at=NOW(),decision_reason=? WHERE id=?',[$d['status'],$u['id'],$reason?:null,$id]);App::query('INSERT INTO application_status_history(application_id,status,note,changed_by) VALUES(?,?,?,?)',[$id,$d['status'],$reason?:'Application reviewed',$u['id']]);if($a['user_id'])App::query('INSERT INTO notifications(user_id,title,message,url) VALUES(?,?,?,?)',[$a['user_id'],'Application '.str_replace('_',' ',$d['status']),$reason?:'Your application status has changed.','/applications']);Automation::emit('application_status_changed',['entity_type'=>'application','entity_id'=>$id,'subject_user_id'=>$a['user_id'],'application_id'=>$id,'form_id'=>$a['form_id'],'form_slug'=>$a['form_slug'],'form_title'=>$a['form_title'],'department_id'=>$a['department_id'],'previous_status'=>$a['status'],'status'=>$d['status'],'reason'=>$reason],(int)$u['id']);});App::redirect('/admin/applications/'.$id);}View::layout('Application #'.$id,function()use($id,$a){View::heading('#'.$id.' · '.$a['form_title'],$a['display_name'].' · '.$a['status']);foreach(App::rows('SELECT q.label,a.answer_text FROM application_answers a JOIN application_questions q ON q.id=a.question_id WHERE a.application_id=? ORDER BY q.sort_order,q.id',[$id]) as $answer){?><section class="review-answer"><h3><?=escape($answer['label'])?></h3><?php View::prose($answer['answer_text']);?></section><?php }View::form('/admin/applications/'.$id.'/status',['status'=>['label'=>'Status','options'=>array_combine(['under_review','changes_requested','interview','accepted','denied','archived'],['Under review','Changes requested','Interview','Accepted','Denied','Archived'])],'reason'=>['label'=>'Decision reason','type'=>'textarea']],'Save decision',$a);});return;}
  if(preg_match('~^/admin/reports/(\d+)(?:/(status|comments))?$~',$path,$m)){$id=(int)$m[1];$r=App::row('SELECT r.*,u.display_name reporter_name FROM reports r LEFT JOIN users u ON u.id=r.reporter_user_id WHERE r.id=?',[$id]);if(!$r)throw new HttpError('Report not found.',404);if($method==='POST'){if(($m[2]??'')==='comments'){App::query('INSERT INTO report_comments(report_id,user_id,comment,is_internal) VALUES(?,?,?,?)',[$id,$u['id'],App::text($d['comment']??null,'Comment',10000),(int)!empty($d['is_internal'])]);}else{if(!in_array($d['status']??'',Domain::REPORT_STATUSES,true))throw new HttpError('Select a valid report status.');App::transaction(function()use($id,$u,$r,$d){if($r['fivem_report_id'])App::row('SELECT id FROM fivem_reports WHERE id=? FOR UPDATE',[$r['fivem_report_id']]);App::row('SELECT id FROM reports WHERE id=? FOR UPDATE',[$id]);App::query('UPDATE reports SET status=?,assigned_to=?,resolution=? WHERE id=?',[$d['status'],$u['id'],$d['resolution']??null,$id]);if($r['fivem_report_id'])App::query('UPDATE fivem_reports SET status=?,assigned_to=? WHERE id=?',[$d['status'],$u['id'],$r['fivem_report_id']]);});}App::redirect('/admin/reports/'.$id);}View::layout('Report #'.$id,function()use($id,$r){View::heading('Report #'.$id,$r['report_type'].' · '.$r['status']);?><section class="panel"><p>Reporter: <?=escape($r['reporter_name'])?></p><p>Reported player: <?=escape($r['reported_name']??'Not provided')?></p><?php View::prose($r['description']);if($r['evidence_url']&&filter_var($r['evidence_url'],FILTER_VALIDATE_URL)&&in_array(parse_url($r['evidence_url'],PHP_URL_SCHEME),['http','https'],true)):?><a href="<?=escape($r['evidence_url'])?>" target="_blank" rel="noopener noreferrer">Evidence</a><?php endif;View::form('/admin/reports/'.$id.'/status',['status'=>['label'=>'Status','options'=>array_combine(Domain::REPORT_STATUSES,Domain::REPORT_STATUSES)],'resolution'=>['label'=>'Resolution','type'=>'textarea']],'Update report',$r);?></section><?php foreach(App::rows('SELECT c.*,u.display_name FROM report_comments c LEFT JOIN users u ON u.id=c.user_id WHERE c.report_id=? ORDER BY c.id',[$id]) as $comment){?><article class="community-entry"><strong><?=escape($comment['display_name'])?></strong><?php View::prose($comment['comment']);?></article><?php }View::form('/admin/reports/'.$id.'/comments',['comment'=>['label'=>'Comment','type'=>'textarea','required'=>true],'is_internal'=>['label'=>'Internal note','type'=>'checkbox','default'=>true]],'Add comment');});return;}
  if($path!=='/admin'&&$path!=='/admin/live')throw new HttpError('Administration page not found.',404);$applications=App::rows('SELECT a.id,a.status,a.submitted_at,f.title form_title,u.display_name FROM applications a JOIN application_forms f ON f.id=a.form_id LEFT JOIN users u ON u.id=a.user_id ORDER BY a.submitted_at DESC LIMIT 50');$reports=App::rows('SELECT r.id,r.report_type,r.reported_name,r.status,r.created_at,u.display_name reporter_name FROM reports r LEFT JOIN users u ON u.id=r.reporter_user_id ORDER BY r.created_at DESC LIMIT 50');if($path==='/admin/live')App::json(['ok'=>true,'applications'=>$applications,'reports'=>$reports,'stats'=>self::stats(),'clockLog'=>self::clockLog(),'updatedAt'=>date(DATE_ATOM)]);View::layout('Admin Center',function()use($u,$applications,$reports){View::heading('Admin Center','Applications, reports and community administration.');?><section class="panel"><h2>Duty clock history</h2><?php View::table(self::clockLog()['sessions'],['display_name'=>'Member','server_name'=>'Server','clocked_in_at'=>'Clock in','clocked_out_at'=>'Clock out','duration_seconds'=>'Seconds']);?></section><?php ?><section class="panel"><h2>Application reviews</h2><?php View::table($applications,['id'=>'ID','form_title'=>'Application','display_name'=>'Member','status'=>'Status'],function($a){?><a href="/admin/applications/<?=(int)$a['id']?>">Review</a><?php });?></section><section class="panel"><h2>Report queue</h2><?php View::table($reports,['id'=>'ID','report_type'=>'Type','reported_name'=>'Reported player','status'=>'Status'],function($r){?><a href="/admin/reports/<?=(int)$r['id']?>">Review</a><?php });?></section><?php if($u['role']==='owner')View::form('/admin/settings/community-name',['community_name'=>['label'=>'Community name','required'=>true,'max'=>120]],'Save community name',['community_name'=>Domain::branding()['name']]);});
 }
 private static function userRole(array $actor,int $id,array $d):void{$roles=['applicant','recruit','member','reviewer',...Domain::STAFF];$role=$d['role']??'';if(!in_array($role,$roles,true))throw new HttpError('Select a valid role.');App::transaction(function()use($actor,$id,$role){$target=App::row('SELECT role FROM users WHERE id=? FOR UPDATE',[$id]);if(!$target)throw new HttpError('User not found.',404);if(($target['role']==='owner'||$role==='owner')&&$actor['role']!=='owner')throw new HttpError('Only an owner can change owner accounts.',403);if($target['role']==='owner'&&$role!=='owner'){$owners=App::rows("SELECT id FROM users WHERE role='owner' AND is_active=1 FOR UPDATE");if(count($owners)<2)throw new HttpError('Keep at least one active owner.',409);}App::query('UPDATE users SET role=? WHERE id=?',[$role,$id]);App::audit((int)$actor['id'],'user.role.update','user',$id,['from'=>$target['role'],'to'=>$role]);});}
 public static function personnel(array $u,int $id):void{Domain::role($u,Domain::STAFF);PersonnelView::render($u,$id);}
 private static function stats():array{$a=App::row("SELECT COALESCE(SUM(status='submitted'),0) pending,COALESCE(SUM(status='under_review'),0) applications_review FROM applications");$r=App::row("SELECT COALESCE(SUM(status='open'),0) open_reports,COALESCE(SUM(status='under_review'),0) reports_review FROM reports");return [...$a,...$r];}
 private static function clockLog():array{return ['sessions'=>App::rows('SELECT p.id,p.status,p.clocked_in_at,p.clocked_out_at,p.callsign,u.display_name,d.name department_name,s.name server_name,TIMESTAMPDIFF(SECOND,p.clocked_in_at,COALESCE(p.clocked_out_at,NOW())) duration_seconds FROM patrol_sessions p JOIN users u ON u.id=p.user_id LEFT JOIN departments d ON d.id=p.department_id LEFT JOIN fivem_servers s ON s.id=p.server_id ORDER BY p.id DESC LIMIT 100'),'events'=>App::rows('SELECT e.id,e.patrol_id,e.event_type,e.source,e.occurred_at,u.display_name FROM patrol_clock_events e JOIN users u ON u.id=e.user_id ORDER BY e.id DESC LIMIT 100')];}

}
